#include "module/mpu6050.hpp"
#include <utility>
namespace fw::module{namespace{constexpr std::uint8_t kWhoAmI=0x75,kPowerMgmt1=0x6B,kSampleRate=0x19,kConfig=0x1A,kGyroConfig=0x1B,kAccelConfig=0x1C,kAccelXoutH=0x3B;std::int16_t s16(const std::uint8_t*p){return static_cast<std::int16_t>((static_cast<std::uint16_t>(p[0])<<8U)|p[1]);}}fw::Result<void>Mpu6050::initialize(){ready_=false;std::uint8_t id=0;auto r=device_.read(kWhoAmI,&id,1);if(!r)return r;if((id&0x7EU)!=0x68U)return fw::Result<void>::failure(fw::Error::DeviceMismatch);const std::uint8_t clock=0x01,rate=0x07,dlpf=0x03,gyro=0x00,accel=0x00;for(auto item:{std::pair<std::uint8_t,std::uint8_t>{kPowerMgmt1,clock},{kSampleRate,rate},{kConfig,dlpf},{kGyroConfig,gyro},{kAccelConfig,accel}}){r=device_.write(item.first,&item.second,1);if(!r)return r;}ready_=true;return fw::Result<void>::success();}fw::Result<Mpu6050Sample>Mpu6050::read(){if(!ready_)return fw::Result<Mpu6050Sample>::failure(fw::Error::NotInitialized);std::uint8_t b[14]{};auto r=device_.read(kAccelXoutH,b,sizeof(b),fw::bsp::TransferMode::Blocking,5U);if(!r)return fw::Result<Mpu6050Sample>::failure(r.error());return fw::Result<Mpu6050Sample>::success({s16(b),s16(b+2),s16(b+4),s16(b+6),s16(b+8),s16(b+10),s16(b+12)});}}
